<template>
	<div class="config-page">
		<form class="config-form" @submit.prevent="saveConfig">
			<label class="config-label" for="config-editor">配置内容</label>

			<textarea
				id="config-editor"
				v-model="editorValue"
				class="config-editor"
				spellcheck="false"
				placeholder="{}"
			></textarea>

			<div class="config-actions">
				<button type="button" :disabled="loading" @click="loadConfig">读取</button>
				<button type="submit" :disabled="loading">保存</button>
				<span class="config-message" :class="{ error: messageType === 'error' }">{{ message }}</span>
			</div>
		</form>
	</div>
</template>

<script setup>
import { onMounted, ref } from 'vue'

const loading = ref(false)
const editorValue = ref('')
const message = ref('')
const messageType = ref('info')

const setMessage = (text, type = 'info') => {
	message.value = text
	messageType.value = type
}

const loadConfig = async () => {
	loading.value = true
	setMessage('Reading /api/config ...')

	try {
		const response = await fetch('/api/config')
		if (!response.ok) {
			throw new Error(`Request failed: ${response.status}`)
		}

		const data = await response.json()
		editorValue.value = `${JSON.stringify(data, null, 2)}\n`
		setMessage('Read success.')
	} catch (err) {
		setMessage(err instanceof Error ? err.message : 'Read failed.', 'error')
	} finally {
		loading.value = false
	}
}

const saveConfig = async () => {
	let payload

	try {
		payload = JSON.parse(editorValue.value)
	} catch {
		setMessage('Invalid JSON.', 'error')
		return
	}

	loading.value = true
	setMessage('Saving /api/config ...')

	try {
		const response = await fetch('/api/config', {
			method: 'PUT',
			headers: {
				'Content-Type': 'application/json'
			},
			body: JSON.stringify(payload)
		})

		if (!response.ok) {
			throw new Error(`Request failed: ${response.status}`)
		}

		const data = await response.json()
		editorValue.value = `${JSON.stringify(data, null, 2)}\n`
		setMessage('Save success.')
	} catch (err) {
		setMessage(err instanceof Error ? err.message : 'Save failed.', 'error')
	} finally {
		loading.value = false
	}
}

onMounted(() => {
	loadConfig()
})
</script>

<style scoped lang="less">
.config-page {
	min-height: 100vh;
	padding: 48px 16px;
	background: #fff;
	color: #222;
	box-sizing: border-box;
	font-family: "Microsoft YaHei", "微软雅黑", sans-serif;
}

.config-form {
	width: 760px;
	max-width: 100%;
	margin: 0 auto;
}

.config-label {
	display: block;
	margin-bottom: 8px;
	font-size: 14px;
}

.config-actions {
	display: flex;
	align-items: center;
	gap: 8px;
	margin-top: 10px;
}

.config-actions button {
	padding: 4px 12px;
	font-family: inherit;
}

.config-message {
	color: #333;
	font-size: 14px;
}

.config-message.error {
	color: #c00;
}

.config-editor {
	width: 100%;
	height: 520px;
	padding: 8px;
	border: 1px solid #999;
	color: #222;
	font-family: "Microsoft YaHei", "微软雅黑", sans-serif;
	font-size: 14px;
	line-height: 1.5;
	box-sizing: border-box;
	resize: vertical;
}
</style>
